import { readFile } from 'node:fs/promises';
import { describe, it, expect } from 'vitest';

// The production page is generated by builder/prod/prod.js, the development page is builder/dev/index.html.
const pages = ['index.html', 'builder/dev/index.html', 'builder/prod/prod.js'];

describe('platform page', () => {
  it.each(pages)('%s has no inline script, as the Content-Security-Policy blocks them', async (pagePath) => {
    const page = await readFile(pagePath, 'utf8');
    expect(page).not.toMatch(/<script(?![^>]*\ssrc=)[^>]*>/i);
    expect(page).toContain('<meta name="base-path" content="%BASE_PATH%">');
  });
});
